-- CONTRACTS (3 rows)
INSERT INTO CONTRACTS (CONTRACT_ID, PAYER_ID, PLAN_ID, PROVIDER_GROUP, EFFECTIVE_DATE, TERM_DATE, FILING_LIMIT_DAYS, APPEAL_WINDOW_DAYS, TIMELY_FILING_DAYS, AUTH_REQUIREMENTS, COVERAGE_NOTES, RESUBMISSION_POLICY, NPI_POLICY, SPECIAL_TERMS) VALUES ('CTR-001', 'PAY-200', 'PREMIER-500', 'Metro Orthopedic Associates', '2025-01-01', '2027-12-31', 90, 60, 120, 'Prior authorization required for all surgical procedures, advanced imaging (MRI/CT), and DME over $500. Auth must reference the performing provider or affiliated group.', 'Covers orthopedic surgery, physical therapy (60 visits/year), advanced imaging, DME. Cardiac care rider available. Remote monitoring covered under cardiac rider Section 7.3.2.', 'Claims denied for missing or incorrect authorization may be resubmitted with correct auth reference within 90 days of initial denial date.', 'Authorizations obtained under a group NPI shall be accepted for claims submitted by any affiliated individual provider within the group. Group-to-individual NPI cross-referencing is the responsibility of the billing entity.', 'Modifier -25 required for separate E/M on same DOS as procedure. Bilateral procedures require modifier -50.');
INSERT INTO CONTRACTS (CONTRACT_ID, PAYER_ID, PLAN_ID, PROVIDER_GROUP, EFFECTIVE_DATE, TERM_DATE, FILING_LIMIT_DAYS, APPEAL_WINDOW_DAYS, TIMELY_FILING_DAYS, AUTH_REQUIREMENTS, COVERAGE_NOTES, RESUBMISSION_POLICY, NPI_POLICY, SPECIAL_TERMS) VALUES ('CTR-002', 'PAY-300', 'VALUE-250', 'Summit Healthcare Network', '2025-06-01', '2027-12-31', 60, 45, 90, 'Prior authorization required for inpatient admits, surgical procedures over $5000, and specialty medications.', 'Standard coverage per plan benefit schedule. Cardiac remote monitoring (CPT 93224-93229) is a covered benefit under Cardiac Care Rider, Section 7.3.2, when ordered by a participating cardiologist and medical necessity is documented.', 'Resubmission within 60 days with corrected information. Second denial on same claim requires formal appeal.', 'Individual provider NPI required on all claims. Group NPI accepted for authorization purposes only.', 'Non-covered services: experimental procedures, cosmetic surgery, weight loss programs unless medically documented.');
INSERT INTO CONTRACTS (CONTRACT_ID, PAYER_ID, PLAN_ID, PROVIDER_GROUP, EFFECTIVE_DATE, TERM_DATE, FILING_LIMIT_DAYS, APPEAL_WINDOW_DAYS, TIMELY_FILING_DAYS, AUTH_REQUIREMENTS, COVERAGE_NOTES, RESUBMISSION_POLICY, NPI_POLICY, SPECIAL_TERMS) VALUES ('CTR-003', 'PAY-400', 'ESSENTIAL-100', 'Peak Regional Medical Group', '2026-01-01', '2028-12-31', 120, 90, 180, 'Prior authorization required for all elective surgeries, advanced diagnostic imaging, and outpatient procedures over $3000.', 'Comprehensive coverage including medical, surgical, behavioral health. Medical necessity review required for post-surgical follow-up beyond standard recovery period.', 'Claims may be resubmitted within 120 days. Appeal must include supporting clinical documentation and provider attestation.', 'Group and individual NPI both accepted for claims and authorizations.', 'All medical necessity determinations follow evidence-based clinical guidelines. Peer-to-peer review available for disputed necessity decisions.');

-- PAYER_DOCS (25 rows)
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-001', 'PAY-200', 'Premier Choice Health', 'Provider Manual', 'Authorization Requirements', '3.1', 'Prior Authorization Overview', 'All surgical procedures, advanced diagnostic imaging (MRI, CT, PET), durable medical equipment over $500, and specialty medications require prior authorization before services are rendered. Authorization requests must be submitted at least 5 business days before the scheduled service date. Emergency and urgent services are exempt from prior authorization requirements but must be reported within 48 hours.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-002', 'PAY-200', 'Premier Choice Health', 'Provider Manual', 'NPI and Authorization Linkage', '3.4', 'Group vs Individual NPI Authorization Policy', 'Authorizations obtained under a group NPI shall be accepted for claims submitted by any affiliated individual provider within the group. When a provider obtains authorization using their group NPI (Type 2), all individual providers (Type 1) who are credentialed members of that group may bill claims referencing that authorization. The billing entity is responsible for ensuring the group-to-individual NPI cross-reference is accurate. Claims denied for missing authorization where a valid group-level authorization exists should be resubmitted with the authorization number and a note referencing this policy section.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-003', 'PAY-200', 'Premier Choice Health', 'Provider Manual', 'Claims Resubmission Policy', '4.1', 'Corrected Claims and Resubmission', 'Claims denied for missing or incorrect authorization may be resubmitted with the correct authorization reference within 90 days of the initial denial date. Resubmissions must include the original claim number, the authorization number, and a cover letter explaining the correction. Frequency limitation: a maximum of two resubmissions per claim are permitted. After two resubmissions, a formal appeal must be filed.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-004', 'PAY-200', 'Premier Choice Health', 'Provider Manual', 'Filing Limits and Deadlines', '4.3', 'Timely Filing Requirements', 'Initial claims must be submitted within 120 days from the date of service. Corrected claims and resubmissions must be filed within 90 days of the denial date. Appeals must be filed within 60 days of the denial date. These deadlines are strictly enforced. Claims submitted after the filing deadline will be denied as untimely and cannot be billed to the member.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-005', 'PAY-200', 'Premier Choice Health', 'Coverage Policy', 'Orthopedic Surgery Coverage', '5.2', 'Knee Arthroscopy and Related Procedures', 'Knee arthroscopy procedures (CPT 29880-29889, 29999) are covered when performed by a participating orthopedic surgeon with prior authorization. Covered indications include meniscal tear, chondral defect, loose body removal, and synovectomy. Documentation must include pre-operative imaging (MRI preferred), failed conservative treatment of at least 6 weeks, and clear surgical indication. Bilateral procedures require separate authorization for each side.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-006', 'PAY-300', 'Value Care Partners', 'Provider Manual', 'Authorization Requirements', '3.1', 'Prior Authorization for Cardiac Services', 'Prior authorization is required for inpatient cardiac admissions, cardiac surgical procedures, cardiac catheterization, and electrophysiology studies. Remote cardiac monitoring services do not require prior authorization when ordered by a participating cardiologist.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-007', 'PAY-300', 'Value Care Partners', 'Coverage Policy', 'Cardiac Monitoring Coverage', '7.3.2', 'Remote Cardiac Monitoring Services', 'Remote cardiac rhythm monitoring (CPT 93224-93229) is a covered benefit under the Cardiac Care Rider when the following criteria are met: (1) The service is ordered by a participating cardiologist, (2) The member has a documented cardiac arrhythmia diagnosis (ICD I48.x, I49.x, I47.x), (3) Monitoring duration is clinically appropriate (typically 7-30 days), (4) The monitoring device is FDA-approved. Coverage includes both the technical component (device application, data transmission, technician review) and the professional component (physician interpretation and report). Claims should be billed with appropriate CPT codes and supporting diagnosis.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-008', 'PAY-300', 'Value Care Partners', 'Coverage Policy', 'Cardiac Care Rider Details', '7.1', 'Cardiac Care Rider Overview', 'The Cardiac Care Rider provides enhanced coverage for cardiac services beyond the base plan benefits. Services covered under this rider include: cardiac rehabilitation programs, remote cardiac monitoring, cardiac imaging (echocardiography, nuclear stress testing), and cardiac device management. This rider is automatically included in Value Care 250 and Premier Value plans. Members with Essential Value plans may add this rider for an additional premium.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-009', 'PAY-300', 'Value Care Partners', 'Provider Manual', 'Appeal Process', '8.1', 'First-Level Appeal Procedures', 'Providers may file a first-level appeal within 45 days of the denial date. Appeals must include: the original claim number, a detailed letter explaining why the denial should be overturned, supporting documentation (clinical records, contract references, policy citations), and any relevant prior appeal decisions for similar claims. The payer will respond within 30 business days. If the first-level appeal is denied, a second-level appeal may be filed within 30 days.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-010', 'PAY-300', 'Value Care Partners', 'Coverage Policy', 'Non-Covered Services', '9.1', 'Exclusions and Limitations', 'The following services are generally not covered: experimental or investigational procedures, cosmetic surgery, weight loss surgery (unless medically documented), services by non-participating providers without authorization, and services exceeding plan frequency limits. However, services listed as non-covered under the base plan may be covered under applicable riders (see Cardiac Care Rider Section 7, Behavioral Health Rider Section 8).', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-011', 'PAY-400', 'Essential Care Network', 'Provider Manual', 'Medical Necessity Standards', '6.1', 'Medical Necessity Determination Framework', 'All services are subject to medical necessity review. Essential Care Network uses evidence-based clinical guidelines for medical necessity determinations. These include nationally recognized clinical criteria, peer-reviewed literature, and specialty society recommendations. Services denied for medical necessity may be appealed through the standard appeals process or through a peer-to-peer review with a board-certified physician in the relevant specialty.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-012', 'PAY-400', 'Essential Care Network', 'Coverage Policy', 'Post-Surgical Follow-up', '6.5', 'Post-Operative Care Coverage', 'Standard post-operative follow-up visits (within 90 days of surgery) are included in the global surgical period and do not require separate authorization. However, additional diagnostic imaging (MRI, CT) or interventional procedures (injections, nerve blocks) performed during the post-operative period require documentation of medical necessity beyond standard recovery. The documentation must demonstrate: (1) failure of expected recovery milestones, (2) new or worsening symptoms not attributable to normal post-operative course, (3) clinical findings on examination that warrant further investigation.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-013', 'PAY-400', 'Essential Care Network', 'Provider Manual', 'Peer-to-Peer Review', '6.3', 'Peer-to-Peer Review Process', 'When a claim is denied for medical necessity, the treating physician may request a peer-to-peer review with a board-certified physician reviewer. The review must be requested within 14 business days of the denial notification. During the peer-to-peer review, the treating physician presents clinical rationale, patient history, and supporting documentation. The reviewer will render a decision within 5 business days of the review.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-014', 'PAY-400', 'Essential Care Network', 'Coverage Policy', 'Spine Surgery and Interventions', '6.7', 'Lumbar Spine Treatment Coverage', 'Lumbar spine surgery (CPT 22551, 22612, 63030, 63047) requires prior authorization and documentation of: (1) failed conservative treatment of at least 12 weeks including physical therapy, (2) diagnostic imaging confirming surgical indication, (3) specialist consultation. Post-surgical follow-up within the 90-day global period is covered. Additional interventions (epidural injections CPT 62320-62327, facet injections CPT 64490-64495) after the global period require separate medical necessity documentation.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-015', 'PAY-400', 'Essential Care Network', 'Provider Manual', 'Appeal Timeline and Requirements', '8.2', 'Appeal Filing Requirements', 'Appeals must be filed within 90 days of the denial date. Required documentation includes: provider attestation letter, relevant medical records, applicable clinical guidelines or literature supporting the service, and any prior peer-to-peer review notes. The payer will respond within 45 business days for standard appeals, 72 hours for expedited appeals involving ongoing treatment.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-016', 'PAY-200', 'Premier Choice Health', 'Coverage Policy', 'Modifier Requirements', '5.5', 'Modifier Usage Guidelines', 'Modifier -25 is required when a significant, separately identifiable E/M service is performed on the same day as a procedure. The E/M must be documented as a separate encounter with its own history, examination, and medical decision-making. Modifier -59 is used to identify procedures that are distinct or independent from other services performed on the same day. Improper modifier usage is a common denial reason and may result in claim recoupment.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-017', 'PAY-200', 'Premier Choice Health', 'SOP', 'Denial Code Reference', '10.1', 'Common Denial Codes and Resolution Paths', 'CO-4: Procedure code inconsistent with modifier — verify modifier is appropriate for CPT billed. CO-16: Claim lacks information — check for missing fields (member ID, DOS, provider NPI). CO-50: Non-covered service — verify benefit schedule and applicable riders. CO-55: Not medically necessary — review clinical documentation, consider peer-to-peer. CO-96: Non-covered charge — similar to CO-50, check plan exclusions. CO-109: Not covered by this payer — verify COB and plan assignment. CO-197: No prior authorization — search for auth under all associated NPIs (individual and group).', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-018', 'PAY-300', 'Value Care Partners', 'SOP', 'Denial Resolution Playbook', '10.2', 'Denial Resolution Strategies by Code', 'CO-50 (Non-covered): First check if a rider applies (Cardiac Rider Section 7, Behavioral Health Rider Section 8). If rider applies, appeal with reference to specific rider section and member enrollment. If no rider, verify the service is truly excluded. CO-55 (Medical necessity): Request peer-to-peer review within 14 days. Gather clinical notes, imaging reports, and specialty consultation notes before the review. CO-197 (No auth): Search for authorization under group NPI if individual NPI search fails. Check date range variations. If auth exists, resubmit; if not, check if service category is exempt from auth.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-019', 'PAY-200', 'Premier Choice Health', 'Provider Manual', 'Coordination of Benefits', '4.5', 'COB Processing Rules', 'When a member has coverage through multiple plans, coordination of benefits rules apply. The primary plan processes the claim first. The secondary plan processes the balance after the primary plan payment. Claims submitted to the secondary plan must include the primary plan EOB. If COB status changes retroactively, claims may be reprocessed within 180 days of the COB status change notification.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-020', 'PAY-300', 'Value Care Partners', 'Coverage Policy', 'Frequency Limitations', '9.3', 'Service Frequency Limits', 'The following frequency limits apply: Office visits limited to 1 per day per provider. Physical therapy limited to 60 visits per calendar year. Advanced imaging (MRI/CT) limited to 2 per body region per 12-month period unless prior auth obtained for additional studies. Remote cardiac monitoring limited to 4 monitoring periods per calendar year. Exceeding frequency limits requires prior authorization and documentation of medical necessity.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-021', 'PAY-400', 'Essential Care Network', 'Coverage Policy', 'Pain Management Coverage', '6.9', 'Chronic Pain Treatment Services', 'Coverage for chronic pain management includes: office visits with pain specialist, physical therapy (up to 40 visits/year), occupational therapy (up to 20 visits/year), epidural steroid injections (up to 3 per 12-month period per spinal region), and medication management. Interventional pain procedures beyond the standard allowance require prior authorization with documentation of: diagnosis, failed conservative measures, functional impact assessment, and treatment plan goals.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-022', 'PAY-200', 'Premier Choice Health', 'Coverage Policy', 'Imaging Requirements', '5.8', 'Pre-Operative Imaging Standards', 'Pre-operative MRI or CT imaging is required within 60 days prior to scheduled orthopedic surgery. The imaging report must be from a participating radiologist and must confirm the surgical indication. X-rays alone are insufficient for authorization of arthroscopic procedures. If imaging is older than 60 days, updated imaging may be required at the discretion of the medical reviewer.', '2025-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-023', 'PAY-300', 'Value Care Partners', 'Provider Manual', 'Provider Network Requirements', '2.3', 'Participating Provider Obligations', 'Participating providers must maintain current credentialing, accept plan-negotiated rates, obtain required authorizations, and submit claims within filing deadlines. Claims from non-participating providers require out-of-network authorization except in emergency situations. Provider NPI must be active and correctly associated with the billing group.', '2025-06-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-024', 'PAY-400', 'Essential Care Network', 'Provider Manual', 'Clinical Documentation Standards', '6.2', 'Documentation Requirements for Medical Necessity', 'All claims subject to medical necessity review must be supported by documentation that includes: chief complaint, relevant history, physical examination findings, diagnostic test results, clinical assessment, and treatment plan rationale. For surgical services, operative notes must include pre-operative diagnosis, post-operative diagnosis, procedure details, findings, and complications. Incomplete documentation is the primary reason for medical necessity denials.', '2026-01-01');
INSERT INTO PAYER_DOCS (DOC_ID, PAYER_ID, PAYER_NAME, DOC_TYPE, DOC_TITLE, SECTION_NUMBER, SECTION_TITLE, CONTENT, EFFECTIVE_DATE) VALUES ('DOC-025', 'PAY-200', 'Premier Choice Health', 'SOP', 'Authorization Search Guide', '3.6', 'Finding Existing Authorizations', 'When a claim is denied for missing authorization, follow this search protocol: (1) Search by member ID and exact date of service, (2) Search by member ID and date range of DOS ± 7 days, (3) Search by group NPI if individual NPI yields no results (per Section 3.4), (4) Search by service category if specific CPT match fails, (5) Check for retro-authorization requests submitted but not yet processed. If an authorization is found, resubmit the claim with the auth reference number and a note citing this search guide.', '2025-01-01');

